package com.sobrenaturaldirector.model.world;
import java.util.*; import com.sobrenaturaldirector.derivation.*;
public final class WorldModel { private final int dimension,playerCount,difficulty; private final long worldAgeTicks,approximateDay; private final int timeOfDay; private final WeatherBand weather; private final List<String> tags; private final Confidence confidence; public WorldModel(int dimension,long age,long day,int time,WeatherBand weather,int difficulty,int players,List<String> tags,Confidence confidence){this.dimension=dimension;worldAgeTicks=age;approximateDay=day;timeOfDay=time;this.weather=weather;this.difficulty=difficulty;playerCount=players;this.tags=Collections.unmodifiableList(new ArrayList<String>(tags));this.confidence=confidence;} public int getDimension(){return dimension;} public long getWorldAgeTicks(){return worldAgeTicks;} public long getApproximateDay(){return approximateDay;} public int getTimeOfDay(){return timeOfDay;} public WeatherBand getWeather(){return weather;} public int getDifficulty(){return difficulty;} public int getPlayerCount(){return playerCount;} public List<String> getTags(){return tags;} public Confidence getConfidence(){return confidence;} }
